import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input = reader.readLine();
        BigDecimal principal = new BigDecimal(input);
        input = reader.readLine();
        BigDecimal rate = new BigDecimal(input);
        input = reader.readLine();
        BigDecimal term = new BigDecimal(input);
        BigDecimal interest = principal.multiply(rate).divide(new BigDecimal(100), 2, RoundingMode.HALF_UP).multiply(term).divide(new BigDecimal(12), 2, RoundingMode.HALF_UP);
        BigDecimal total = principal.add(interest);
        System.out.println("INTEREST=" + String.format(Locale.ROOT, "%010.2f", interest.abs()));
        System.out.println("TOTAL=" + String.format(Locale.ROOT, "%010.2f", total.abs()));
    }
}
